s = open('b_mal2.py', encoding='utf-8').read()
s = s.replace("2: dict(B08='band', B09='band', B14='linie', B03='rot', B11='linie0', B10='linie0', B12='linie0')}", "2: dict(B08='band2', B09='band2', B14='linie', B03='rot', B11='linie0', B10='linie0', B12='linie0')}")
s = s.replace("TON = dict(linie=LINIE[1], linie0=LINIE[0], band=BAND[1], band0=BAND[0], rot=ROT[1])", "TON = dict(linie=LINIE[1], linie0=LINIE[0], band=BAND[1], band0=BAND[0], band2=BAND[2], rot=ROT[1])")
s = s.replace("    rgb[ok & (k[y, x] > 0)] = ROT[1]        # FORMBLATT 2.1: Hakeninneres rotbraun\n", "    rgb[ok & (k[y, x] > 0)] = ROT[2]        # FORMBLATT 2.1: Hakeninneres rotbraun\n")
