s = s.replace("    durchgang(a.fit, a.tag, a.ab, a.snap, malen=M2.malen, wahl=WAHL)\n", "    durchgang(a.fit, a.tag, a.ab, a.snap, malen=M2.malen, wahl=WAHL, runden=a.runden)\n")
